print('total',d['summary']['total'],'passed',d['summary']['passed'])
for c in d['checks']: print(('  OK  ' if c['passed'] else '  FAIL'), c['id'],'|',str(c['detail'])[:300])
print(); print('inventoryRowForATs:',d['observations'].get('inventoryRowForATs'))
"

